// Replays the golden vectors generated by scripts/generate-flow-vectors.ts
// against the C++ port and compares canonical serializations. A mismatch
// means the two implementations of the decision layer disagree — fix the C++
// side (the TS side is the reference) or regenerate stale vectors.
#include <clocale>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <sstream>
#include <string>

#include "../flow_json.h"
#include "../native_config.h"
#include "../update_flow_core.h"

using flowjson::Parse;
using flowjson::Stringify;
using flowjson::Value;

namespace {

Value Dispatch(const std::string& fn, const Value& args, bool* known) {
  *known = true;
  if (fn == "murmurhash3_32_gc") {
    return Value::Number(flowcore::Murmur3_32(args.At(0).AsString()));
  }
  if (fn == "isInRollout") {
    return Value::Bool(
        flowcore::IsInRollout(args.At(0).AsNumber(), args.At(1).AsString()));
  }
  if (fn == "isMirrorRetryableCode") {
    return Value::Bool(
        flowcore::IsMirrorRetryableCode(args.At(0).AsString()));
  }
  if (fn == "joinUrls") {
    return flowcore::JoinUrls(args.At(0), args.At(1));
  }
  if (fn == "orderEndpointCandidates") {
    return flowcore::OrderEndpointCandidates(args.At(0),
                                               args.At(1).AsNumber());
  }
  if (fn == "buildCheckRequestBody") {
    return flowcore::BuildRequestBody(args.At(0));
  }
  if (fn == "resolveCheckResult") {
    return flowcore::ResolveResult(args.At(0), args.At(1));
  }
  if (fn == "decideDownload") {
    return flowcore::DecideDownload(args.At(0), args.At(1),
                                      args.At(2).Truthy());
  }
  if (fn == "isValidCheckResponse") {
    return Value::Bool(
        flowcore::IsValidResponse(args.At(0).AsString()));
  }
  if (fn == "shouldActivateAfterDownload") {
    return Value::Bool(flowcore::ShouldActivateAfterDownload(
        args.At(0), args.At(1).AsString()));
  }
  *known = false;
  return Value::Undefined();
}

// The parser consumes network data (checkUpdate responses); malformed and
// hostile inputs must set ok=false without crashing — this suite runs under
// ASan+UBSan in CI. Valid-but-tricky inputs pin the JS JSON.parse semantics
// the port relies on.
int RunParserRobustness() {
  int failures = 0;

  const char* malformed[] = {
      "",
      "{",
      "[1,2",
      "\"abc",
      "{\"a\":}",
      "{\"a\" 1}",
      "{\"a\":1,}",
      "[1,]",
      "tru",
      "nul",
      "falsy",
      "1x",
      "1 2",
      "- 1",
      "01",
      "-01",
      "1.",
      "1e",
      "1e+",
      "\"\\q\"",
      "\"\\u12\"",
      "\"\\ud800\\u12\"",  // malformed escape after a high surrogate
      "{\"a\":1}garbage",
      "[}",
      "{]",
  };
  for (const char* input : malformed) {
    bool ok = true;
    Parse(input, &ok);
    if (ok) {
      std::fprintf(stderr, "robustness: accepted malformed input: %s\n", input);
      failures++;
    }
  }

  // Nesting: 64 levels parse, 65 are rejected (stack-depth cap).
  for (int depth : {64, 65}) {
    std::string nested;
    for (int i = 0; i < depth; i++) {
      nested.push_back('[');
    }
    for (int i = 0; i < depth; i++) {
      nested.push_back(']');
    }
    bool ok = false;
    Parse(nested, &ok);
    bool expected = depth <= 64;
    if (ok != expected) {
      std::fprintf(stderr, "robustness: depth %d parsed=%d, expected %d\n",
                   depth, ok, expected);
      failures++;
    }
  }
  // A deeply nested bomb must fail cleanly, not overflow the stack.
  {
    std::string bomb(100000, '[');
    bool ok = true;
    Parse(bomb, &ok);
    if (ok) {
      std::fprintf(stderr, "robustness: accepted nesting bomb\n");
      failures++;
    }
  }

  // Valid-but-tricky inputs: assert the parsed value via canonical stringify.
  const struct {
    const char* input;
    const char* expected;
  } tricky[] = {
      // Duplicate keys: first position, last value (JSON.parse semantics).
      {"{\"a\":1,\"b\":2,\"a\":3}", "{\"a\":3,\"b\":2}"},
      {"\"\\u00e9\"", "\"\xc3\xa9\""},                    // BMP escape -> UTF-8
      {"\"\\ud83d\\ude00\"", "\"\xf0\x9f\x98\x80\""},     // surrogate pair
      // Lone surrogates parse (JSON.parse accepts them) but never produce
      // invalid UTF-8: each becomes U+FFFD.
      {"\"\\ud800\"", "\"\xef\xbf\xbd\""},
      {"\"\\udc00\"", "\"\xef\xbf\xbd\""},
      {"\"\\ud800x\"", "\"\xef\xbf\xbdx\""},
      {"\"\\ud800\\u0041\"", "\"\xef\xbf\xbd" "A\""},  // high + non-low escape
      {"\"\\ud800\\ud83d\\ude00\"", "\"\xef\xbf\xbd\xf0\x9f\x98\x80\""},
      {"  {  \"a\" : [ 1 , true , null ] }  ", "{\"a\":[1,true,null]}"},
      {"-0.5", "-0.5"},
      {"1e2", "100"},
      {"1E2", "100"},
      {"-0", "0"},
      {"0.125", "0.125"},  // exact binary fractions only: %.17g fallback
      {"25e-2", "0.25"},
      {"1e400", "null"},   // Infinity: JSON.stringify prints null
      {"-1e400", "null"},
      {"1e-400", "0"},
  };
  for (const auto& t : tricky) {
    bool ok = false;
    Value v = Parse(t.input, &ok);
    std::string actual = Stringify(v);
    if (!ok || actual != t.expected) {
      std::fprintf(stderr,
                   "robustness: %s -> ok=%d %s (expected %s)\n", t.input, ok,
                   actual.c_str(), t.expected);
      failures++;
    }
  }

  // Same duplicate-key rule once an object is large enough to be parsed
  // through the hash index: k0..k19, then k0 and k17 again.
  {
    std::string input = "{";
    std::string expected = "{";
    for (int i = 0; i < 20; i++) {
      const std::string key = "\"k" + std::to_string(i) + "\":";
      input += key + std::to_string(i) + ",";
      expected += key +
                  (i == 0 ? std::string("100") : i == 17 ? std::string("117")
                                                         : std::to_string(i)) +
                  (i == 19 ? "}" : ",");
    }
    input += "\"k0\":100,\"k17\":117}";
    bool ok = false;
    std::string actual = Stringify(Parse(input, &ok));
    if (!ok || actual != expected) {
      std::fprintf(stderr, "robustness: large duplicate-key object -> %s\n",
                   actual.c_str());
      failures++;
    }
  }

  return failures;
}

// Number conversion is hand-rolled (locale-independent); pin it against the
// C-locale strtod for the exactly-representable range the decision layer
// uses, and check the process locale cannot change parse or print.
int RunNumberConversion() {
  int failures = 0;
  const char* tokens[] = {
      "0", "-0", "1", "-1", "7", "42", "100", "1.5", "-1.5", "0.1", "0.05",
      "0.125", "123456789", "4294967295", "9007199254740992",
      "-9007199254740992", "1719999999", "1e2", "1E2", "1e+2", "12e-1",
      "1e22", "1e-22", "1.7e12", "12345678901234567e10", "2.5e-3",
      "1e37", "4e37", "9007199254740992e15",
  };
  // Outside the exact-rounding contract (a significand over 2^53) the
  // parser documents a possible one-ulp difference from strtod; pin those
  // tokens to within one ulp instead of bit-for-bit.
  const char* approximate_tokens[] = {"12345678901234567e10"};
  for (const char* token : tokens) {
    bool ok = false;
    Value v = Parse(token, &ok);
    const double expected = std::strtod(token, nullptr);
    const double actual = v.AsNumber();
    bool approximate = false;
    for (const char* candidate : approximate_tokens) {
      approximate = approximate || std::strcmp(candidate, token) == 0;
    }
    const bool matches =
        approximate
            ? actual == expected ||
                  actual == std::nextafter(expected, -INFINITY) ||
                  actual == std::nextafter(expected, INFINITY)
            : std::memcmp(&expected, &actual, sizeof(double)) == 0;
    if (!ok || !v.IsNumber() || !matches) {
      std::fprintf(stderr, "number: %s -> ok=%d %.17g (expected %.17g)\n",
                   token, ok, actual, expected);
      failures++;
    }
  }
  {
    bool ok = false;
    Value inf = Parse("1e400", &ok);
    if (!ok || !std::isinf(inf.AsNumber()) || inf.AsNumber() < 0) {
      std::fprintf(stderr, "number: 1e400 must saturate to +Infinity\n");
      failures++;
    }
    Value zero = Parse("1e-400", &ok);
    if (!ok || zero.AsNumber() != 0) {
      std::fprintf(stderr, "number: 1e-400 must underflow to 0\n");
      failures++;
    }
  }

  // A host process may setlocale() into a comma-decimal locale; neither
  // parsing nor printing may notice. Skipped when no such locale is installed.
  const char* comma_locales[] = {"de_DE.UTF-8", "de_DE.utf8", "de_DE",
                                 "fr_FR.UTF-8", "fr_FR.utf8", "fr_FR"};
  const char* applied = nullptr;
  for (const char* name : comma_locales) {
    if (std::setlocale(LC_NUMERIC, name) != nullptr) {
      applied = name;
      break;
    }
  }
  if (applied != nullptr) {
    char probe[32];
    std::snprintf(probe, sizeof(probe), "%.1f", 1.5);
    if (std::strcmp(probe, "1,5") == 0) {
      bool ok = false;
      Value v = Parse("{\"r\":1.5,\"n\":-0.25}", &ok);
      const std::string printed = Stringify(v);
      if (!ok || v.Get("r").AsNumber() != 1.5 ||
          printed != "{\"r\":1.5,\"n\":-0.25}") {
        std::fprintf(stderr, "locale %s: parse ok=%d printed=%s\n", applied,
                     ok, printed.c_str());
        failures++;
      }
      std::printf("number conversion checked under %s\n", applied);
    }
    std::setlocale(LC_NUMERIC, "C");
  } else {
    std::printf("no comma-decimal locale installed; locale check skipped\n");
  }
  return failures;
}

// Input caps (flow_json.h): oversized or over-populated documents are
// rejected before they can balloon the heap.
int RunInputCaps() {
  int failures = 0;
  {
    std::string exact = "\"" + std::string(flowjson::kMaxInputBytes - 2, 'a') + "\"";
    bool ok = false;
    Parse(exact, &ok);
    if (!ok) {
      std::fprintf(stderr, "caps: a document of exactly kMaxInputBytes must parse\n");
      failures++;
    }
    std::string over = "\"" + std::string(flowjson::kMaxInputBytes - 1, 'a') + "\"";
    ok = true;
    Parse(over, &ok);
    if (ok) {
      std::fprintf(stderr, "caps: a document over kMaxInputBytes must be rejected\n");
      failures++;
    }
  }
  {
    // The array itself is one node: kMaxNodes - 1 elements fit, kMaxNodes do not.
    for (size_t elements : {flowjson::kMaxNodes - 1, flowjson::kMaxNodes}) {
      std::string doc = "[";
      for (size_t i = 0; i < elements; i++) {
        doc += i == 0 ? "0" : ",0";
      }
      doc += "]";
      bool ok = false;
      Parse(doc, &ok);
      const bool expected = elements < flowjson::kMaxNodes;
      if (ok != expected) {
        std::fprintf(stderr, "caps: %zu elements parsed=%d, expected %d\n",
                     elements, ok, expected);
        failures++;
      }
    }
  }
  {
    // Caller-chosen caps (ParseLimits) replace both defaults, in either
    // direction.
    flowjson::ParseLimits limits;
    limits.max_input_bytes = 8;
    limits.max_nodes = 3;
    bool ok = false;
    Parse("[1,2]", limits, &ok);
    if (!ok) {
      std::fprintf(stderr, "caps: 3 nodes within an 8-byte cap must parse\n");
      failures++;
    }
    ok = true;
    Parse("[1,2,3]", limits, &ok);
    if (ok) {
      std::fprintf(stderr, "caps: a 4th node over max_nodes must be rejected\n");
      failures++;
    }
    ok = true;
    Parse("\"abcdefg\"", limits, &ok);
    if (ok) {
      std::fprintf(stderr, "caps: 9 bytes over max_input_bytes must be rejected\n");
      failures++;
    }
    limits.max_input_bytes = flowjson::kMaxInputBytes + 16;
    limits.max_nodes = 1;
    ok = false;
    Parse("\"" + std::string(flowjson::kMaxInputBytes, 'a') + "\"", limits, &ok);
    if (!ok) {
      std::fprintf(stderr, "caps: a raised max_input_bytes must admit the document\n");
      failures++;
    }
  }
  {
    // Through the pipeline an oversized body is an invalid response.
    std::string body = "{\"update\":true,\"hash\":\"h\",\"pad\":\"" +
                       std::string(flowjson::kMaxInputBytes, 'x') + "\"}";
    Value decision = flowcore::HandleResponse(body, Value::Object(),
                                                     false, "none");
    if (decision.Get("reason").AsString() != "invalidResponse") {
      std::fprintf(stderr, "caps: oversized body must yield invalidResponse\n");
      failures++;
    }
  }
  return failures;
}

// HandleResponse is pure composition (no decision logic of its own), so
// it is tested directly here instead of via TS-generated vectors: response
// text in, canonical decision out.
int RunHandleCheckResponse() {
  int failures = 0;
  Value identity = Value::Object();
  identity.Set("packageVersion", Value::String("2.3.4"));
  identity.Set("currentVersion", Value::String("cur"));
  identity.Set("uuid", Value::String("test1"));  // bucket 62
  identity.Set("rolledBackVersion", Value::String("bad"));

  const struct {
    const char* name;
    const char* response;
    const char* afterDownload;
    const char* expected;
  } cases[] = {
      {"malformed", "not json{", "none",
       "{\"action\":\"none\",\"reason\":\"invalidResponse\"}"},
      {"non-object", "[1,2]", "none",
       "{\"action\":\"none\",\"reason\":\"invalidResponse\"}"},
      {"upToDate", "{\"upToDate\":true}", "none",
       "{\"action\":\"none\",\"reason\":\"noUpdate\",\"info\":{\"upToDate\":"
       "true}}"},
      {"expired",
       "{\"expired\":true,\"downloadUrl\":\"https://x/app.apk\"}", "none",
       "{\"action\":\"none\",\"reason\":\"noUpdate\",\"info\":{\"expired\":"
       "true,\"downloadUrl\":\"https://x/app.apk\"}}"},
      {"alreadyCurrent",
       "{\"update\":true,\"hash\":\"cur\",\"full\":\"cur.ppk\","
       "\"paths\":[\"cdn.x.com\"]}",
       "none",
       "{\"action\":\"none\",\"reason\":\"noUpdate\",\"info\":{\"upToDate\":"
       "true}}"},
      {"download",
       "{\"update\":true,\"hash\":\"h2\",\"full\":\"h2.ppk\","
       "\"paths\":[\"cdn.x.com\"],\"name\":\"v2\"}",
       "none",
       "{\"action\":\"download\",\"hash\":\"h2\",\"attempts\":[{\"type\":"
       "\"full\",\"urls\":[\"https://cdn.x.com/h2.ppk\"]}],\"devNoop\":false,"
       "\"activate\":false,"
       "\"info\":{\"update\":true,\"hash\":\"h2\",\"full\":\"h2.ppk\","
       "\"paths\":[\"cdn.x.com\"],\"name\":\"v2\"}}"},
      {"download-silent-strategy",
       "{\"update\":true,\"hash\":\"h2\",\"full\":\"h2.ppk\","
       "\"paths\":[\"cdn.x.com\"]}",
       "setNeedUpdate",
       "{\"action\":\"download\",\"hash\":\"h2\",\"attempts\":[{\"type\":"
       "\"full\",\"urls\":[\"https://cdn.x.com/h2.ppk\"]}],\"devNoop\":false,"
       "\"activate\":true,"
       "\"info\":{\"update\":true,\"hash\":\"h2\",\"full\":\"h2.ppk\","
       "\"paths\":[\"cdn.x.com\"]}}"},
      {"download-forceBoot",
       "{\"update\":true,\"hash\":\"h2\",\"full\":\"h2.ppk\","
       "\"paths\":[\"cdn.x.com\"],\"config\":{\"forceBoot\":true}}",
       "none",
       "{\"action\":\"download\",\"hash\":\"h2\",\"attempts\":[{\"type\":"
       "\"full\",\"urls\":[\"https://cdn.x.com/h2.ppk\"]}],\"devNoop\":false,"
       "\"activate\":true,"
       "\"info\":{\"update\":true,\"hash\":\"h2\",\"full\":\"h2.ppk\","
       "\"paths\":[\"cdn.x.com\"],\"config\":{\"forceBoot\":true}}}"},
      {"rollout-in-forceBoot",
       "{\"update\":true,\"hash\":\"root\",\"full\":\"root.ppk\","
       "\"paths\":[\"cdn.x.com\"],\"expVersion\":{\"name\":\"g\",\"hash\":"
       "\"gray\",\"full\":\"gray.ppk\",\"config\":{\"rollout\":{\"2.3.4\":"
       "63},\"forceBoot\":true}}}",
       "none",
       "{\"action\":\"download\",\"hash\":\"gray\",\"attempts\":[{\"type\":"
       "\"full\",\"urls\":[\"https://cdn.x.com/gray.ppk\"]}],\"devNoop\":"
       "false,\"activate\":true,"
       "\"info\":{\"update\":true,\"name\":\"g\",\"hash\":\"gray\","
       "\"full\":\"gray.ppk\",\"config\":{\"rollout\":{\"2.3.4\":63},"
       "\"forceBoot\":true},\"paths\":[\"cdn.x.com\"]}}"},
      {"rollout-out",
       "{\"update\":true,\"hash\":\"root\",\"full\":\"root.ppk\","
       "\"paths\":[\"cdn.x.com\"],\"expVersion\":{\"name\":\"g\",\"hash\":"
       "\"gray\",\"full\":\"gray.ppk\",\"config\":{\"rollout\":{\"2.3.4\":"
       "62}}}}",
       "none",
       "{\"action\":\"download\",\"hash\":\"root\",\"attempts\":[{\"type\":"
       "\"full\",\"urls\":[\"https://cdn.x.com/root.ppk\"]}],\"devNoop\":"
       "false,\"activate\":false,\"info\":{\"update\":true,\"hash\":\"root\","
       "\"full\":\"root.ppk\",\"paths\":[\"cdn.x.com\"]}}"},
      {"rolledBack-wins-over-forceBoot",
       "{\"update\":true,\"hash\":\"bad\",\"full\":\"bad.ppk\","
       "\"paths\":[\"cdn.x.com\"],\"config\":{\"forceBoot\":true}}",
       "none",
       "{\"action\":\"none\",\"reason\":\"rolledBack\",\"info\":{\"update\":"
       "true,\"hash\":\"bad\",\"full\":\"bad.ppk\",\"paths\":[\"cdn.x.com\"],"
       "\"config\":{\"forceBoot\":true}}}"},
  };
  for (const auto& c : cases) {
    Value decision = flowcore::HandleResponse(c.response, identity,
                                                     false, c.afterDownload);
    std::string actual = Stringify(decision);
    if (actual != c.expected) {
      std::fprintf(stderr,
                   "handleResponse %s MISMATCH\n  expected: %s\n"
                   "  actual:   %s\n",
                   c.name, c.expected, actual.c_str());
      failures++;
    }
  }
  return failures;
}

// Contract C1: every case must hold in both argument orders (shared with
// the JS implementation, src/__tests__/configEquivalenceVectors.test.ts).
int RunConfigEquivalence(const Value& doc) {
  int failures = 0;
  const Value& cases = doc.Get("cases");
  if (!cases.IsArray() || cases.Size() < 30) {
    std::fprintf(stderr, "config equivalence vectors: too few cases\n");
    return 1;
  }
  for (const Value& c : cases.elements()) {
    const std::string& a = c.Get("a").AsString();
    const std::string& b = c.Get("b").AsString();
    const bool expected = c.Get("equivalent").AsBool();
    if (flowcore::ConfigsEquivalent(a, b) != expected ||
        flowcore::ConfigsEquivalent(b, a) != expected) {
      std::fprintf(stderr, "config equivalence \"%s\" MISMATCH (expected %s)\n",
                   c.Get("name").AsString().c_str(),
                   expected ? "equivalent" : "different");
      failures++;
    }
  }
  return failures;
}

int RunNativeConfig(const Value& doc) {
  int failures = 0;
  const Value& runnable = doc.Get("runnable");
  const Value& normalize = doc.Get("normalize");
  if (!runnable.IsArray() || runnable.Size() == 0 || !normalize.IsArray() ||
      normalize.Size() == 0) {
    std::fprintf(stderr, "native config vectors: missing cases\n");
    return 1;
  }
  for (const Value& c : runnable.elements()) {
    const std::string actual =
        flowcore::RunnableConfigJson(c.Get("config").AsString());
    const std::string expected = Stringify(c.Get("expected"));
    if (actual != expected) {
      std::fprintf(stderr,
                   "runnable \"%s\" MISMATCH\n  expected: %s\n  actual:   %s\n",
                   c.Get("name").AsString().c_str(), expected.c_str(),
                   actual.c_str());
      failures++;
    }
  }
  for (const Value& c : normalize.elements()) {
    std::string out;
    std::string error;
    const bool ok = flowcore::NormalizeConfiguration(
        c.Get("options").AsString(), &out, &error);
    const std::string actual = ok ? out : "error: " + error;
    const Value& expectedValue = c.Get("expected");
    const std::string expected = expectedValue.IsString()
                                     ? expectedValue.AsString()
                                     : "error: " + c.Get("error").AsString();
    if (actual != expected) {
      std::fprintf(stderr,
                   "normalize \"%s\" MISMATCH\n  expected: %s\n  actual:   %s\n",
                   c.Get("name").AsString().c_str(), expected.c_str(),
                   actual.c_str());
      failures++;
      continue;
    }
    // A normalized config is what the gate later reads: it must be
    // runnable (or disabled) and equivalent to itself.
    if (ok) {
      const flowcore::RunnableConfig gate = flowcore::ParseRunnableConfig(out);
      if (!(gate.runnable() || gate.reason == "disabled") ||
          !flowcore::ConfigsEquivalent(out, out)) {
        std::fprintf(stderr, "normalize \"%s\": output not runnable/stable\n",
                     c.Get("name").AsString().c_str());
        failures++;
      }
    }
  }
  return failures;
}

int RunTrimAndDeepEquals() {
  int failures = 0;
  const struct {
    const char* input;
    const char* expected;
  } trims[] = {
      {"", ""},
      {"   ", ""},
      {"\t\n\v\f\r k \r\n", "k"},
      {"\xc2\xa0k\xe3\x80\x80", "k"},             // NBSP, U+3000
      {"\xef\xbb\xbfk\xe2\x80\xa8", "k"},         // BOM, U+2028
      {"\xe2\x80\x8ak\xe2\x80\xaf\xe2\x81\x9f", "k"},  // U+200A U+202F U+205F
      {"\xe1\x9a\x80k", "k"},                     // U+1680
      {"\xe2\x80\x8bk", "\xe2\x80\x8bk"},          // U+200B is not whitespace
      {"\x01k\x1f", "\x01k\x1f"},                  // C0 controls are kept
      {"\xc2\x85k", "\xc2\x85k"},                  // U+0085 (NEL) is kept
      {"a b", "a b"},
      {"\xc2", "\xc2"},                            // truncated sequence
  };
  for (const auto& t : trims) {
    if (flowcore::TrimJsWhitespace(t.input) != t.expected) {
      std::fprintf(stderr, "TrimJsWhitespace(\"%s\") MISMATCH\n", t.input);
      failures++;
    }
  }
  const auto parse = [](const char* text) {
    bool ok = false;
    return Parse(text, &ok);
  };
  const struct {
    const char* a;
    const char* b;
    bool equal;
  } pairs[] = {
      {"{\"a\":1,\"b\":[1,{\"c\":null}]}", "{\"b\":[1,{\"c\":null}],\"a\":1}", true},
      {"{\"a\":1}", "{\"a\":1,\"b\":2}", false},
      {"{\"a\":1,\"b\":2}", "{\"a\":1}", false},
      {"[1,2]", "[2,1]", false},
      {"1", "1.0", true},
      {"0", "false", false},
      {"null", "null", true},
      {"\"1\"", "1", false},
      {"[]", "{}", false},
  };
  for (const auto& p : pairs) {
    if (Value::DeepEquals(parse(p.a), parse(p.b)) != p.equal) {
      std::fprintf(stderr, "DeepEquals(%s, %s) MISMATCH\n", p.a, p.b);
      failures++;
    }
  }
  // Undefined members count as absent.
  Value withUndefined = Value::Object();
  withUndefined.Set("a", Value::Number(1));
  withUndefined.Set("b", Value::Undefined());
  if (!Value::DeepEquals(withUndefined, parse("{\"a\":1}")) ||
      !Value::DeepEquals(parse("{\"a\":1}"), withUndefined)) {
    std::fprintf(stderr, "DeepEquals: undefined member is not absent\n");
    failures++;
  }
  return failures;
}

bool LoadJson(const char* path, Value* doc) {
  std::ifstream file(path);
  if (!file) {
    std::fprintf(stderr, "cannot open %s\n", path);
    return false;
  }
  std::stringstream buffer;
  buffer << file.rdbuf();
  bool ok = false;
  *doc = Parse(buffer.str(), &ok);
  if (!ok) {
    std::fprintf(stderr, "failed to parse %s\n", path);
  }
  return ok;
}

}  // namespace

int main(int argc, char* argv[]) {
  if (argc < 4) {
    std::fprintf(stderr,
                 "usage: %s <flow_vectors.json> "
                 "<config-equivalence-vectors.json> "
                 "<native-config-vectors.json>\n",
                 argv[0]);
    return 2;
  }
  Value doc;
  Value equivalenceDoc;
  Value nativeConfigDoc;
  if (!LoadJson(argv[1], &doc) || !LoadJson(argv[2], &equivalenceDoc) ||
      !LoadJson(argv[3], &nativeConfigDoc)) {
    return 2;
  }

  const Value& cases = doc.Get("cases");
  if (!cases.IsArray() || cases.Size() == 0) {
    std::fprintf(stderr, "%s must contain a non-empty cases array\n", argv[1]);
    return 2;
  }
  int failures = RunParserRobustness() + RunNumberConversion() +
                 RunInputCaps() + RunHandleCheckResponse() +
                 RunConfigEquivalence(equivalenceDoc) +
                 RunNativeConfig(nativeConfigDoc) + RunTrimAndDeepEquals();
  for (size_t i = 0; i < cases.Size(); i++) {
    const Value& testCase = cases.At(i);
    const std::string& fn = testCase.Get("fn").AsString();
    bool known = false;
    Value actual = Dispatch(fn, testCase.Get("args"), &known);
    if (!known) {
      std::fprintf(stderr, "case %zu: unknown fn %s\n", i, fn.c_str());
      failures++;
      continue;
    }
    std::string actualStr = Stringify(actual);
    std::string expectedStr = Stringify(testCase.Get("expected"));
    if (actualStr != expectedStr) {
      std::fprintf(stderr,
                   "case %zu (%s) MISMATCH\n  args:     %s\n  expected: %s\n"
                   "  actual:   %s\n",
                   i, fn.c_str(), Stringify(testCase.Get("args")).c_str(),
                   expectedStr.c_str(), actualStr.c_str());
      failures++;
    }
  }

  if (failures) {
    std::fprintf(stderr,
                 "%d failures (%zu flow vectors, config vectors + parser "
                 "robustness)\n",
                 failures, cases.Size());
    return 1;
  }
  std::printf(
      "all %zu flow vectors, %zu config equivalence vectors, %zu+%zu native "
      "config vectors + parser robustness passed\n",
      cases.Size(), equivalenceDoc.Get("cases").Size(),
      nativeConfigDoc.Get("runnable").Size(),
      nativeConfigDoc.Get("normalize").Size());
  return 0;
}
